+function frame(t){if(state==='playing')return;const dt=Math.min((t-lastTime)/1000,.04);lastTime=t;if(state==='menu'){elapsed+=dt;beatFlash=Math.max(0,beatFlash-dt*3.4);if(Math.floor(elapsed/BEAT)!==Math.floor((elapsed-dt)/BEAT)){beatFlash=1;beatSound()}}draw();requestAnimationFrame(frame)}
