const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://localhost:3002',{waitUntil:'networkidle'});await page.screenshot({path:'/tmp/opencode/neonrun.jpg',type:'jpeg',quality:80});
 await page.getByRole('button',{name:/START RUN/}).click();await page.waitForTimeout(600);await page.keyboard.press('Space');await page.waitForTimeout(300);
 const state=await page.evaluate(()=>({title:document.querySelector('#title').textContent,score:document.querySelector('#score').innerText,fill:document.querySelector('#progressFill').style.width}));
 console.log(JSON.stringify({errors,state}));await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
